import { execFileSync } from "node:child_process";

try {
	execFileSync("mise", ["exec", "hk", "--", "hk", "install", "--mise"], {
		stdio: "inherit",
	});
} catch (error) {
	if (error?.code === "ENOENT") {
		console.warn(
			"mise is not installed; skipping hk hook installation. See CONTRIBUTING.md.",
		);
	} else {
		console.warn("hk hook installation failed; continuing npm install.");
	}
}

amends "package://github.com/jdx/hk/releases/download/v1.51.0/hk@1.51.0#/Config.pkl"
import "package://github.com/jdx/hk/releases/download/v1.51.0/hk@1.51.0#/Builtins.pkl"

local linters = new Mapping<String, Step> {
    ["oxlint"] {
        glob = List(
            "**/*.js",
            "**/*.ts",
            "**/*.cjs",
            "**/*.mjs",
            "**/*.d.cts",
            "**/*.d.mts",
            "**/*.jsx",
            "**/*.tsx",
        )
        check = "npx oxlint --type-aware --type-check ."
    }
    ["oxfmt"] {
        glob = List(
            "**/*.js",
            "**/*.ts",
            "**/*.cjs",
            "**/*.mjs",
            "**/*.d.cts",
            "**/*.d.mts",
            "**/*.jsx",
            "**/*.tsx",
            "**/*.json",
            "**/*.jsonc",
            "**/*.md",
        )
        depends = "oxlint"
        check = "npx oxfmt --check {{files}}"
        fix = "npx oxfmt --write {{files}}"
    }
    ["actionlint"] {
        glob = List(
            ".github/workflows/**/*.yml",
            ".github/workflows/**/*.yaml",
        )
        check = "actionlint"
    }
    ["zizmor"] {
        glob = List(
            ".github/dependabot.yml",
            ".github/workflows/**/*.yml",
            ".github/workflows/**/*.yaml",
            "**/action.yml",
            "**/action.yaml",
        )
        depends = "actionlint"
        check = "zizmor --offline --strict-collection --collect=default --format=plain ."
    }
}

hooks {
    ["pre-commit"] {
        fix = true
        stash = "git"
        steps {
            ...linters
            ["tests"] {
                check = "npm run test:unit"
            }
        }
    }
    ["commit-msg"] {
        steps {
            ["commitlint"] {
                check = "npx commitlint --edit {{commit_msg_file}}"
            }
        }
    }
    ["pre-push"] {
        steps {
            ["repository-control-plane"] {
                check = "npx nx run repository:pre-push"
            }
        }
    }
    ["fix"] {
        fix = true
        steps = linters
    }
    ["check"] {
        steps = linters
    }
}

