Author:     Christoph Kieslich <c.kieslich@gmail.com>
AuthorDate: Sat Aug 1 16:40:59 2026 +0200
Commit:     Christoph Kieslich <c.kieslich@gmail.com>
CommitDate: Sat Aug 1 16:40:59 2026 +0200

    build: install hk hooks during npm install
---
 package.json                  |  1 +
 scripts/install-git-hooks.mjs | 15 +++++++++++++++
 2 files changed, 16 insertions(+)

diff --git a/package.json b/package.json
index 08be550..bf309d3 100644
--- a/package.json
+++ b/package.json
@@ -35,6 +35,7 @@
 	],
 	"type": "module",
 	"scripts": {
+		"prepare": "node scripts/install-git-hooks.mjs",
 		"inspect": "npm run build && npx @modelcontextprotocol/inspector@latest node --env-file .env packages/node/dist/cli.mjs",
 		"inspect:npm": "npx @modelcontextprotocol/inspector@latest npx hevy-mcp@latest",
 		"measure:tokens": "tsx scripts/measure-token-cost.ts",
diff --git a/scripts/install-git-hooks.mjs b/scripts/install-git-hooks.mjs
new file mode 100644
index 0000000..b164193
--- /dev/null
+++ b/scripts/install-git-hooks.mjs
@@ -0,0 +1,15 @@
+import { execFileSync } from "node:child_process";
+
+try {
+	execFileSync("mise", ["exec", "hk", "--", "hk", "install", "--mise"], {
+		stdio: "inherit",
+	});
+} catch (error) {
+	if (error?.code === "ENOENT") {
+		console.warn(
+			"mise is not installed; skipping hk hook installation. See CONTRIBUTING.md.",
+		);
+	} else {
+		console.warn("hk hook installation failed; continuing npm install.");
+	}
+}

