import { execFileSync } from "node:child_process";
import { existsSync } from "node:fs";
import { join, resolve } from "node:path";

const hooksPath = ".githooks";
const hookNames = ["pre-commit", "commit-msg", "pre-push"];

function git(args, options = {}) {
	return execFileSync("git", ["-C", process.cwd(), ...args], options);
}

function gitText(args) {
	return git(args, {
		encoding: "utf8",
		stdio: ["ignore", "pipe", "ignore"],
	}).trim();
}

function repositoryRoot() {
	try {
		return gitText(["rev-parse", "--show-toplevel"]);
	} catch {
		return null;
	}
}

function usesWorktreeConfig() {
	try {
		return gitText(["config", "--get", "extensions.worktreeConfig"]) === "true";
	} catch {
		return false;
	}
}

const root = repositoryRoot();

if (!root) {
	console.warn("Not a Git checkout; skipping Git hook setup.");
} else {
	const missingHooks = hookNames.filter(
		(hookName) => !existsSync(join(root, hooksPath, hookName)),
	);

	if (missingHooks.length > 0) {
		throw new Error(
			`Missing tracked Git hooks under ${hooksPath}: ${missingHooks.join(", ")}`,
		);
	}

	try {
		const configScope = usesWorktreeConfig() ? "--worktree" : "--local";
		git(["config", configScope, "core.hooksPath", hooksPath], {
			stdio: "inherit",
		});

		const effectiveHooksPath = gitText(["rev-parse", "--git-path", "hooks"]);
		if (resolve(root, effectiveHooksPath) !== resolve(root, hooksPath)) {
			throw new Error(
				`Git is still using ${effectiveHooksPath} instead of ${hooksPath}`,
			);
		}

		console.log(`Git hooks enabled through ${hooksPath}.`);
	} catch (error) {
		console.error(
			"Unable to configure Git hooks. Run `npm run prepare` again after fixing the repository configuration.",
		);
		throw error;
	}
}

