+import { execFile } from "node:child_process";
+import {
+	chmod,
+	cp,
+	mkdir,
+	mkdtemp,
+	readFile,
+	rm,
+	writeFile,
+} from "node:fs/promises";
+import { tmpdir } from "node:os";
+import { dirname, join, resolve } from "node:path";
+import { promisify } from "node:util";
+import { fileURLToPath } from "node:url";
+import { afterEach, describe, expect, it } from "vitest";
+
+const execFileAsync = promisify(execFile);
+const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
+const installer = join(root, "scripts/install-git-hooks.mjs");
+const hookNames = ["pre-commit", "commit-msg", "pre-push"];
+const fixtures: string[] = [];
+
+function environment(repo: string, overrides: NodeJS.ProcessEnv = {}) {
+	return {
+		...process.env,
+		GIT_CONFIG_GLOBAL: join(repo, "global.gitconfig"),
+		GIT_CONFIG_NOSYSTEM: "1",
+		...overrides,
+	};
+}
+
+async function git(repo: string, ...args: string[]) {
+	return execFileAsync("git", args, {
+		cwd: repo,
+		env: environment(repo),
+	});
+}
+
+async function createRepository() {
+	const repo = await mkdtemp(join(tmpdir(), "hevy-mcp-hooks-"));
+	fixtures.push(repo);
+	await git(repo, "init", "--quiet");
+	await mkdir(join(repo, ".githooks"));
+
+	await Promise.all(
+		hookNames.map(async (hookName) => {
+			const source = join(root, ".githooks", hookName);
+			const target = join(repo, ".githooks", hookName);
+			await cp(source, target);
+			await chmod(target, 0o755);
+		}),
+	);
+
+	await git(repo, "config", "user.name", "Hook Test");
+	await git(repo, "config", "user.email", "hook-test@example.com");
+	return repo;
+}
+
+async function runInstaller(repo: string, env: NodeJS.ProcessEnv = {}) {
+	return execFileAsync(process.execPath, [installer], {
+		cwd: repo,
+		env: environment(repo, env),
+	});
+}
+
+afterEach(async () => {
+	await Promise.all(
+		fixtures
+			.splice(0)
+			.map((fixture) => rm(fixture, { recursive: true, force: true })),
+	);
+});
+
+describe("Git hook setup", () => {
+	it("configures Git to use the tracked hook wrappers", async () => {
+		const repo = await createRepository();
+		await git(repo, "config", "--local", "core.hooksPath", ".other-hooks");
+
+		await runInstaller(repo);
+
+		const { stdout } = await git(
+			repo,
+			"config",
+			"--local",
+			"--get",
+			"core.hooksPath",
+		);
+		expect(stdout.trim()).toBe(".githooks");
+	});
+
+	it("overrides a worktree-specific hook path", async () => {
+		const repo = await createRepository();
+		await git(repo, "config", "extensions.worktreeConfig", "true");
+		await git(repo, "config", "--worktree", "core.hooksPath", ".other-hooks");
+
+		await runInstaller(repo);
+
+		const { stdout } = await git(
+			repo,
+			"config",
+			"--worktree",
+			"--get",
+			"core.hooksPath",
+		);
+		expect(stdout.trim()).toBe(".githooks");
+	});
+
+	it("runs commit hooks through mise", async () => {
+		const repo = await createRepository();
+		await runInstaller(repo);
+
+		const bin = join(repo, "bin");
+		const log = join(repo, "hook.log");
+		const mise = join(bin, "mise");
+		await mkdir(bin);
+		await writeFile(mise, '#!/bin/sh\nprintf \'%s\\n\' "$*" >> "$HOOK_LOG"\n');
+		await chmod(mise, 0o755);
+		await writeFile(join(repo, "tracked.txt"), "hook test\n");
+		await git(repo, "add", ".");
+
+		await execFileAsync(
+			"git",
